import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Color, DoubleSide } from 'three/webgpu';
import { uv, mix, smoothstep, float, texture } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup } = ctx.THREE;

  // Root group
  const root = new Group();

  // Plate geometry and material
  const plateWidth = 4.0;
  const plateHeight = 2.5;
  const geometry = new PlaneGeometry(plateWidth, plateHeight, 64, 64);
  const plateMaterial = new MeshStandardNodeMaterial({
    side: DoubleSide,
    transparent: true,
    roughness: 0.6,
    metalness: 0.1,
    opacity: 0,
  });
  const plateMesh = new Mesh(geometry, plateMaterial);
  root.add(plateMesh);

  // Load main texture
  let mainTex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      mainTex = tex;
      plateMaterial.map = tex;
      plateMaterial.needsUpdate = true;
    });
  }

  // Load depth map and apply displacement node
  let depthTex = null;
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTex = tex;
      const dispNode = texture(tex).r.mul(float(0.18));
      plateMaterial.displacementNode = dispNode;
      plateMaterial.needsUpdate = true;
    });
  }

  // Bottom scrim gradient plane
  const scrimGeom = new PlaneGeometry(plateWidth, plateHeight, 1, 1);
  const scrimMat = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
  });
  // Gradient: transparent at 0.45, opaque at 1.0 using the same hue #0b0b10
  scrimMat.colorNode = mix(
    new Color('#0b0b10').toArray(),
    new Color('#0b0b10').toArray(),
    smoothstep(float(0.45), float(1.0), uv().y)
  );
  scrimMat.alphaNode = smoothstep(float(0.45), float(1.0), uv().y);
  const scrimMesh = new Mesh(scrimGeom, scrimMat);
  scrimMesh.position.z = 0.001; // slightly in front of plate
  root.add(scrimMesh);

  // Caption block
  const captionGroup = new Group();
  const basePadding = 0.5; // 2 × base unit (0.25)
  captionGroup.position.set(
    -plateWidth / 2 + basePadding,
    -plateHeight / 2 + basePadding,
    0.01
  );
  root.add(captionGroup);

  // Text items extraction
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const baseline = 0.25;
  let cursorY = 0;

  // Helper to create text objects
  const createText = (content, opts) => {
    const defaults = {
      fontSize: 13,
      color: config.visualSpec?.colors?.paper ?? '#e8ecf2',
    };
    const finalOpts = Object.assign({}, defaults, opts);
    const txt = ctx.fontAtlas.createText(content, finalOpts);
    txt.position.set(0, cursorY, 0);
    captionGroup.add(txt);
    cursorY += baseline;
    return txt;
  };

  // Kicker
  createText('NOVA ATELIER / GENEVA', {
    fontSize: 9,
    color: config.visualSpec?.colors?.paper ?? '#e8ecf2',
    letterSpacing: 0.12,
    fontWeight: 700,
  });

  // Headline
  createText('Time, Machined.', {
    fontSize: 34,
    color: config.visualSpec?.colors?.paper ?? '#e8ecf2',
    letterSpacing: -0.01,
    fontWeight: 600,
  });

  // Accent hairline bar between headline and body
  const barWidth = 0.75;
  const barHeight = 0.02;
  const barGeom = new PlaneGeometry(barWidth, barHeight);
  const barMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.8,
    metalness: 0,
    roughness: 1,
    side: DoubleSide,
    transparent: true,
  });
  const barMesh = new Mesh(barGeom, barMat);
  // Position bar roughly halfway between headline and next line
  barMesh.position.set(0, cursorY - baseline * 0.5, 0.001);
  captionGroup.add(barMesh);

  // Body
  createText('Every case begins as a single billet of 904L steel.', {
    fontSize: 13,
    color: config.visualSpec?.colors?.paper ?? '#e8ecf2',
    fontWeight: 400,
  });

  // Caption (small)
  createText('CALIBRE NA-01 / 72 HOUR RESERVE', {
    fontSize: 9,
    color: config.visualSpec?.colors?.paper ?? '#e8ecf2',
    fontWeight: 400,
    letterSpacing: 0.12,
  });

  // Animation timelines
  const masterTL = gsap.timeline();

  // Plate fade-in
  masterTL.to(plateMaterial, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });

  // Caption rise-in after 120 ms delay
  captionGroup.position.y += 0.4;
  masterTL.to(
    captionGroup.position,
    {
      y: '-=0.4',
      duration: 0.7,
      ease: 'cubic-bezier(0.215,0.61,0.355,1)',
    },
    '+=0.12'
  );

  // Apply cinematic primitives
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params);
        primitiveInstances.push(instance);
      }
    }
  }

  // UserData handlers placeholder (none defined)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    masterTL.kill();
    primitiveInstances.forEach((inst) => {
      if (inst && typeof inst.cleanup === 'function') inst.cleanup();
    });
    plateMaterial.dispose();
    scrimMat.dispose();
    barMat.dispose();
    geometry.dispose();
    scrimGeom.dispose();
    barGeom.dispose();
    if (mainTex) mainTex.dispose();
    if (depthTex) depthTex.dispose();
    // Dispose any text objects if they expose dispose (optional)
    captionGroup.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose?.();
      if (obj.material) obj.material.dispose?.();
    });
  };

  return root;
}
